// 一级菜单采用唯一归属：病历页面属于“病历中心”，不再同时属于“门诊工作台”。
const outpatientRoutes=['outpatient','opd-record','opd-diagnosis','opd-orders','opd-results','opd-consult','opd-followup'];
const emergencyRoutes=['emergency','er-triage','er-record','er-nursing','er-observation','er-handoff'];
const inpatientRoutes=['inpatient','inpatient-overview','inpatient-course',...inpatientDocRoutes,'ip-orders','ip-results','ip-consult','ip-pathway','inpatient-discharge'];
const isPrimaryActive=p=>current===p.id
  ||(p.id==='record'&&recordRoutes.includes(current))
  ||(p.id==='outpatient'&&outpatientRoutes.includes(current)&&!recordRoutes.includes(current))
  ||(p.id==='emergency'&&emergencyRoutes.includes(current))
  ||(p.id==='inpatient-course'&&inpatientDocRoutes.includes(current))
  ||(p.id==='inpatient'&&['ip-orders','ip-results','ip-consult','ip-pathway'].includes(current))
  ||(p.id==='archive-assets'&&archiveRoutes.includes(current))
  ||(p.id==='integration'&&integrationRoutes.includes(current))
  ||(p.id==='research'&&researchRoutes.includes(current))
  ||(p.id==='admin'&&adminRoutes.includes(current));
function shell(content){
  let groups=''; [...new Set(pages.map(p=>p.group))].forEach(g=>{groups+=`<div class="nav-group">${g}</div>`;pages.filter(p=>p.group===g).forEach(p=>groups+=`<button class="nav-item ${isPrimaryActive(p)?'active':''}" data-page="${p.id}"><span class="nav-icon">${p.icon}</span><span>${p.label}</span>${p.count?`<b class="nav-count">${p.count}</b>`:''}</button>`)});
  const inpatientDomain=inpatientRoutes.includes(current);
  const emergencyDomain=emergencyRoutes.includes(current);
  const outpatientDomain=outpatientRoutes.includes(current);
  const roleContext=current==='clinical'?'临床业务门户':emergencyDomain?'急诊医生 · 抢救区':current==='ward'?'病区护士 · 心内科一病区':inpatientDomain?'住院医生 · 心内科一病区':recordRoutes.includes(current)?'病历中心 · 当前门诊就诊':outpatientDomain?'门诊医生 · 心内科':current==='clinical-tasks'?'统一临床任务中心':archiveRoutes.includes(current)?'病案资产与长期保存':integrationRoutes.includes(current)?'集成与互操作管理':researchRoutes.includes(current)?'科研数据利用':adminRoutes.includes(current)?'机构系统管理员 · 生产环境':current==='credentials'?'医务与资质管理':'管理与治理工作台';
  const searchHint=emergencyDomain?'搜索急诊患者、急诊号、腕带码':inpatientDomain||current==='ward'?'搜索住院患者、床号、住院号':recordRoutes.includes(current)?'搜索当前患者病历、文书、来源或版本':outpatientDomain?'搜索门诊患者、门诊号、身份证号':archiveRoutes.includes(current)?'搜索病案号、资产 ID、CDA 文档':integrationRoutes.includes(current)?'搜索系统、连接器、Trace ID':researchRoutes.includes(current)?'搜索科研项目、队列、数据集':adminRoutes.includes(current)?'搜索用户、角色、字典、参数或审计':'搜索患者、任务或功能';
  return `<div class="shell"><header class="topbar"><div class="brand"><b class="brand-mark">+</b><span>HaoEMR<small>OPEN MEDICAL RECORD</small></span></div><div class="context-pill">江城大学附属医院⌄</div><div class="context-pill domain-context">${roleContext}⌄</div><div class="top-search"><input placeholder="${searchHint}"></div><div class="top-actions"><button class="icon-btn">?</button><button class="icon-btn">♢</button><div class="avatar">林</div><div class="user-meta"><b>林医生</b><br><small>今日 08:00–17:00</small></div></div></header><aside class="sidebar">${groups}</aside><main class="main">${content}</main></div>`;
}
