const domainNav=(domain,active)=>{const maps={outpatient:[['outpatient','门诊工作台'],['opd-record','门诊病历'],['opd-diagnosis','诊断'],['opd-orders','医嘱处方'],['opd-results','检查检验'],['opd-consult','会诊转诊'],['opd-followup','随访终诊']],emergency:[['emergency','急诊工作台'],['er-triage','预检分诊'],['er-record','急诊病历'],['er-observation','抢救留观'],['er-nursing','急诊护理'],['er-handoff','急会诊与交接']],inpatient:[['inpatient','患者列表'],['inpatient-overview','患者总览'],['inpatient-course','病历文书'],['ip-orders','医嘱与用药'],['ip-results','检查检验'],['ip-consult','查房会诊'],['ip-pathway','临床路径'],['ward','护理摘要'],['inpatient-discharge','出院病案']]};const items=maps[domain]||maps.inpatient;const activeKey=inpatientDocRoutes.includes(active)?'inpatient-course':active;return `<div class="domain-nav ${domain}"><button class="domain-home" data-jump="clinical">⌂ 临床业务门户</button><span class="domain-divider"></span>${items.map(x=>`<button class="${x[0]===activeKey?'active':''}" data-jump="${x[0]}">${x[1]}</button>`).join('')}</div>`};
