function clinical(){const opModules=[['预约挂号与队列','号源、到诊、分诊、叫号、过号'],['门诊病历与质控','主诉、病史、查体、诊断、签署'],['医嘱处方与执行','药品、检验、检查、治疗、审方'],['结果与危急值','趋势、报告更正、确认与处置'],['会诊转诊','申请、受理、意见、时限'],['随访与终诊','教育、复诊、随访、结束就诊']];const ipModules=[['在院患者与任务','床位、医疗组、风险、责任与时限'],['住院总览','诊断、医嘱、体征、结果、护理摘要'],['病历文书与查房','入院、首程、病程、三级查房、审签'],['医嘱用药与执行','长期/临时医嘱、给药、停止与重整'],['会诊手术与协同','会诊、手术、转科、交班、事件文书'],['出院病案闭环','出院记录、首页、质控、整改、归档']];const domainCard=(type,title,desc,jump,metrics,alerts,flow,modules,footer)=>`<section class="domain-card ${type}-domain"><div class="domain-hero"><div class="domain-symbol">${title[0]}</div><div><div class="domain-eyebrow">${type.toUpperCase()} CARE</div><h2>${title}</h2><p>${desc}</p></div><button class="btn domain-enter ${type==='outpatient'?'primary':''}" data-jump="${jump}">进入${title} →</button></div><div class="domain-metrics">${metrics.map(x=>`<div><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div><div class="domain-alerts">${alerts.map(x=>`<span class="status ${x[2]}">${x[0]} ${x[1]}</span>`).join('')}</div><div class="domain-flow"><b>诊疗主线</b>${flow.map((x,i)=>`${i?'<i>›</i>':''}<span>${x}</span>`).join('')}</div><div class="module-map">${modules.map(x=>`<button data-jump="${x[2]}"><b>${x[0]}</b><small>${x[1]}</small></button>`).join('')}</div><div class="domain-footer">${footer.map(x=>`<div><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div></section>`;const op=domainCard('outpatient','门诊诊疗','以一次门诊就诊为中心，从预约到诊、问诊病历、诊断医嘱到签署终诊。','outpatient',[['今日挂号','46'],['已到诊','21'],['候诊','6'],['诊疗中','2'],['待结果','5'],['待签病历','3']],[['危急值','1','red'],['处方待审','2','amber'],['会诊临期','1','amber']],['预约挂号','到诊分诊','问诊病历','诊断医嘱','结果处置','签署终诊'],opModules.map((x,i)=>[x[0],x[1],['outpatient','record','opd-orders','opd-results','opd-consult','opd-followup'][i]]),[['当前上下文','心内科 · 门诊医生 · 今日班次'],['最近访问','陈建国 · OP20260813-0842 · 草稿已保存']]);const er=domainCard('emergency','急诊诊疗','以时间关键事件为主线，从预检分诊、抢救留观、急会诊交接到明确去向。','emergency',[['急诊在区','18'],['一级抢救','2'],['待分诊','4'],['留观','9'],['急会诊','3'],['待去向','4']],[['绿色通道','2','red'],['抢救记录待补','1','amber'],['交接临期','2','amber']],['院前 / 到院','预检分诊','抢救 / 诊室','急诊医嘱','会诊交接','去向闭环'],[['预检分诊与分区','级别、依据、改区、绿色通道','er-triage'],['急诊病历与抢救','时间轴、抢救记录、医嘱结果','er-record'],['急诊护理与输液','生命体征、执行、异常','er-nursing'],['急会诊与交接班','时限、责任、未完任务','er-handoff'],['留观与转住院','观察记录、去向、接收','er-observation'],['时间关键质控','双时间、超时、补录原因','er-record']],[['当前上下文','急诊抢救区 · 白班 · 林医生'],['最高风险','胸痛中心绿色通道 · 7 分钟前到院']]);const ip=domainCard('inpatient','住院诊疗','以连续住院为中心，从入院接管、医嘱执行、病程查房到出院归档。','inpatient',[['在管患者','12'],['病危 / 病重','2 / 4'],['新入院','2'],['文书逾期','2'],['异常结果','3'],['拟出院','3']],[['危急值','1','red'],['首程逾期','1','red'],['路径变异','2','amber']],['入院接管','入院 / 首程','医嘱执行','病程查房','会诊手术','出院归档'],ipModules.map((x,i)=>[x[0],x[1],['inpatient','inpatient-overview','inpatient-course','ip-orders','ip-consult','inpatient-discharge'][i]]),[['当前上下文','心内科一病区 · A 医疗组'],['最近访问','李桂兰 · 02床 · 首程待完成']]);return pageHead('临床业务门户','一级入口 · 门诊、急诊、住院三个独立临床工作域 · 数据更新 09:45','<button class="btn" data-jump="clinical-tasks">统一任务 9</button><button class="btn">工作设置</button>')+`<div class="portal-safety"><b>工作域安全边界</b><span>三域共享患者主索引和时间线，但患者、就诊、草稿、任务筛选、搜索和 AI 会话分别隔离。</span><span class="status green">核心服务正常</span></div><div class="domain-split domain-triple">${op}${er}${ip}</div><div class="portal-bottom"><div data-jump="clinical-tasks"><b>统一任务与临床路径</b><span>危急值 · 会诊 · 审签 · 时限 · 路径变异 · 出院整改</span></div><div data-jump="archive-assets"><b>病案资产与 CDA</b><span>电子文书 · 签字扫描件 · 共享文档 · CA · 无纸化归档</span></div><div data-jump="credentials"><b>专科与资质扩展</b><span>专科能力包 · 移动查房 PWA · 处方/手术/技术授权</span></div></div>`}
