function render(){if(!renderers[current])current='clinical';let content=renderers[current]();if(outpatientRoutes.includes(current))content=domainNav('outpatient',current)+content;if(emergencyRoutes.includes(current))content=domainNav('emergency',current)+content;if(inpatientRoutes.includes(current)||current==='ward')content=domainNav('inpatient',current)+content;document.getElementById('app').innerHTML=shell(content);if(current==='inpatient-course'){const grid=document.querySelector('.course-layout');const review=[...document.querySelectorAll('.card-head')].find(x=>x.textContent.includes('质控、来源与审签'))?.parentElement;if(grid&&review&&review.parentElement!==grid)grid.append(review)}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{current=b.dataset.page;location.hash=current;render()});document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{current=b.dataset.jump;location.hash=current;render()});}
window.addEventListener('hashchange',()=>{current=location.hash.slice(1)||'clinical';render()});render();
